const STY = (acc) => `position:absolute;left:70px;width:800px;height:200px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:linear-gradient(180deg,color-mix(in srgb,${acc} 72%,#fff),${acc} 55%,color-mix(in srgb,${acc} 84%,#000));color:#0b1020;font-family:inherit;font-weight:800;line-height:1.1;font-size:42px;opacity:0;box-sizing:border-box;padding:20px;text-transform:uppercase;`;

root.innerHTML = `
  <div id="c0" style="${STY('var(--acc)')}top:80px;">COMMAND:<br>market-regime-daily</div>
  <div id="c1" style="${STY('var(--acc2)')}top:360px;">SOURCE:<br>LOCAL CSV FILES</div>
  <div id="c2" style="${STY('var(--acc)')}top:640px;">0% API COSTS<br>MAX EFFICIENCY</div>
  <div id="st" style="position:absolute;top:920px;left:0;width:940px;text-align:center;color:#ffffff;font-size:48px;font-weight:900;opacity:0;letter-spacing:-1px;">4,170 GITHUB STARS</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 280 L470 360" />
    <path id="l1" d="M470 560 L470 640" />
  </svg>
`;

const items = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2')];
const stars = root.querySelector('#st');
const lines = [root.querySelector('#l0'), root.querySelector('#l1')].map(el => {
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Cards Entrance
  const cardDelays = [0.2, 1.2, 2.2];
  items.forEach((el, i) => {
    const s = spr(tf, cardDelays[i], 0.8, 7);
    el.style.opacity = clamp(s * 2);
    const scale = lerp(0.8, 1, E_OUT(clamp(s)));
    const yMove = lerp(50, 0, E_OUT(clamp(s)));
    el.style.transform = `translateY(${yMove}px) scale(${scale})`;
  });

  // Line Drawing
  const lineDelays = [0.9, 1.9];
  lines.forEach((line, i) => {
    const s = clamp((tf - lineDelays[i]) * 2);
    line.el.style.strokeDashoffset = line.len * (1 - E_INOUT(s));
  });

  // GitHub Stars count up & fade
  const starS = spr(tf, 2.8, 0.8, 6);
  stars.style.opacity = clamp(starS);
  stars.style.transform = `translateY(${lerp(20, 0, starS)}px)`;
  const starCount = Math.floor(lerp(0, 4170, E_OUT(clamp((tf - 2.8) * 1.5))));
  stars.textContent = starCount.toLocaleString() + ' GITHUB STARS';
}
